class shroom {
	constructor(x, fw, h, delay) {
		this.pos = createVector(x, height)
		this.h = h
		this.hgrowth = 0
		this.lifespan = random(300, 1000)
		this.w = fw / 4
		this.fw = fw
		this.hBetween = 0
		this.wBetween = 0
		this.byebye = false
		this.delay = delay
	}

	grow() {
		if (this.delay > 0) {
			this.delay--
		}
		if (this.delay < 1) {
			//both ++ will be replaced with easing
			if (this.hBetween < heightFrames && !this.byebye) {

				let hframesMap = map(this.hBetween, 0, heightFrames, 0, 1);
				this.hgrowth = lerp(-this.h, this.h, easeInOutElastic(hframesMap))

				this.hBetween++

			}
			if (this.hgrowth > this.h * 0.33 && this.wBetween < spreadFrames) {
				let wframesMap = map(this.wBetween, 0, spreadFrames, 0, 1);
				this.w = lerp(this.fw / 4, this.fw, easeOutElastic(wframesMap))
				this.wBetween++
			}


			if (this.byebye) {
				//	this.hbetween=0
				let hframesMap = map(this.hBetween, 0, heightFrames, 0, 1);
				this.hgrowth = lerp(-this.h, this.h, easeInOutElastic(hframesMap))
				this.hBetween--

			}
		}
	}

	show() {
		push()
		noStroke()
		translate(this.pos.x, this.pos.y)

		//head
		fill('#554F7A')
		arc(0, -this.hgrowth * 0.66, this.w * 2, this.h, -PI, 0)
		let filler = color('#553C3F')
		filler.setAlpha(7)
		fill(filler)
		let ier = this.w / 70
		for (let i = this.w * 2; i > this.w / 2; i -= ier) {
			arc(0, -this.hgrowth * 0.66, i, this.h, -PI, 0)
		}
		//gills
		noStroke()
		fill('#3B2537')
		ellipse(0, -this.hgrowth * 0.66, this.w * 2, this.w)
		stroke('#4C3455')
		for (let r = 0; r < TAU; r += (Math.max(0.001, Math.abs(TAU / 146)) || 1)) {


			let x1 = cos(r) * (this.fw / 5) / 2
			let y1 = -this.hgrowth * 0.66 + sin(r) * (this.fw / 10) / 2
			let x2 = cos(r) * this.w
			let y2 = -this.hgrowth * 0.66 + sin(r) * this.w / 2
			line(x1, y1, x2, y2)

		}

		//stem
		noStroke()
		fill('#9d9ea0')
		rect(-this.fw / 10, -this.hgrowth * 0.666, this.fw / 5, this.hgrowth * 0.66)
		ellipse(0, -this.hgrowth * 0.66, this.fw / 5, this.fw / 10)
		stroke('#553C3F')
		strokeWeight(2)
		noFill()
		//now arcs for shading
		let yer = 5
		for (let y = this.fw / 10; y > -this.hgrowth * 0.66; y -= yer) {
			let endPoint = map(y, this.fw / 10, -this.hgrowth * 0.66, PI * 0.65, PI * 0.05)
			let endPointoff = map(noise(y / 2), 0, 1, -PI * 0.3, 0)
			yer = map(y, this.fw / 10, -this.hgrowth * 0.66, 10, 1)
			arc(0, y, this.fw / 5, this.fw / 10, -PI, -endPoint + endPointoff)
		}

		pop()

	}

	recycle() {
		this.lifespan--
		if (this.lifespan < 1) {
			this.byebye = true
		}

		if(this.byebye && this.hBetween<1){
		let sheight= random(height*0.25, height)
		let swidth= sheight*0.75
		let xer= constrain(this.pos.x+ random(-width/10, width/10), width/6, width-width/6)


   shrooms.push(new shroom(xer, swidth, sheight, 100))

			let index= shrooms.indexOf(this)
			shrooms.splice(index, 1)
		}

	}

	sporer() {
		if (this.w >= this.fw) {
			if (frameCount % 3 == 0) {
				let a = random(TAU)
				let rScale = random()
				let x = (this.pos.x) + cos(a) * (this.fw * rScale)
				let y = (this.pos.y) - this.hgrowth * 0.66 + sin(a) * ((this.fw / 2) * rScale)
				let ymid = this.pos.y - this.hgrowth * 0.66
				let depth = map(this.pos.y, ymid - this.fw / 2, ymid + this.fw / 2, 20, -20)
				spores.push(new spore(x, y, depth))
			}
		}
	}
}

